// China administrative boundaries (province + prefecture/city level),
// generated at build time from DataV GeoAtlas (geo.datav.aliyun.com areas_v3),
// itself derived from public administrative-division data. Rings are flat
// [lng, lat, ...] pairs, Douglas-Peucker simplified (province eps 0.02 deg,
// city eps 0.03 deg), coordinates rounded to 3 decimals.
// Payload format (perf repack, 2026-11-18): the integer stream is
// zigzag-varint encoded and base64-packed into string literals instead
// of comma-separated number arrays — identical values after decode,
// but the bundle shrinks by ~half and the JS parser sees a few string
// literals instead of millions of number tokens (the arrays dominated
// cold-start parse time on phones).
// Each unit's rings are packed as one integer stream:
// [ringCount, per ring: pointCount, dLng, dLat, ...] (degrees x1000).

export interface AdminUnit { name: string; full: string; center: [number, number] | null; rings: number[][] }

interface PackedUnit { name: string; full: string; center: [number, number] | null; packed: string }

function unpackInts(packed: string): number[] {
  const bin = atob(packed);
  const out: number[] = [];
  let i = 0;
  while (i < bin.length) {
    let u = 0;
    let shift = 0;
    for (;;) {
      const b = bin.charCodeAt(i++);
      u += (b & 0x7f) * 2 ** shift;
      if (!(b & 0x80)) break;
      shift += 7;
    }
    out.push(u % 2 === 0 ? u / 2 : -(u + 1) / 2);
  }
  return out;
}

function decodeRings(enc: number[]): number[][] {
  const rings: number[][] = [];
  let i = 0;
  while (i < enc.length) {
    const n = enc[i++] ?? 0;
    const ring: number[] = [];
    let l = 0;
    let a = 0;
    for (let k = 0; k < n; k++) {
      l += enc[i++] ?? 0;
      a += enc[i++] ?? 0;
      ring.push(l / 1000, a / 1000);
    }
    rings.push(ring);
  }
  return rings;
}

function unpackUnit(p: PackedUnit): AdminUnit {
  const stream = unpackInts(p.packed);
  return {
    name: p.name,
    full: p.full,
    center: p.center,
    rings: decodeRings(stream.slice(1)),
  };
}

